<template><main class="hh-page authorizations"><router-link to="/referencias" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a referencias</router-link><section class="auth-hero"><div><span>AUDITORÍA ASISTENCIAL</span><h1>Autorizaciones adicionales</h1><p>Revise y responda solicitudes de paquetes durante la atención.</p></div><div><label><input v-model="filters.urgentes" type="checkbox" class="form-check-input">Solo urgentes</label><button class="btn btn-light text-primary" @click="load"><i class="ph ph-arrows-clockwise me-1"></i>Actualizar</button></div></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><section v-else class="auth-list mt-4"><div v-if="!items.length" class="empty"><i class="ph ph-seal-check"></i><h3>Sin autorizaciones pendientes</h3><p>La bandeja operativa se encuentra al día.</p></div><article v-for="item in items" :key="item.id" :class="{urgent:item.urgente}"><header><div><span v-if="item.urgente"><i class="ph ph-warning"></i>URGENTE</span><small>{{item.referencia?.numero_referencia||`Referencia #${item.referencia_id}`}}</small><h3>{{item.paquete?.nombre||'Paquete adicional'}}</h3></div><span class="status">{{item.estado?.nombre||item.estado||'Pendiente'}}</span></header><div class="auth-body"><div><small>Paciente</small><strong>{{item.referencia?.paciente?.nombre||item.paciente?.nombre||'No informado'}}</strong></div><div><small>Cantidad</small><strong>{{item.cantidad}}</strong></div><div><small>Solicitante</small><strong>{{item.solicitante?.name||item.solicitado_por||'No informado'}}</strong></div><div class="reason"><small>Motivo</small><p>{{item.motivo_solicitud}}</p><small>Justificación médica</small><p>{{item.justificacion_medica||'Sin justificación adicional'}}</p></div></div><footer><router-link :to="`/referencias/${item.referencia_id||item.referencia?.id}`" class="btn btn-outline-primary">Abrir referencia</router-link><button class="btn btn-outline-danger" @click="respond(item,'reject')">Rechazar</button><button class="btn btn-success" @click="respond(item,'approve')">Aprobar</button></footer></article></section><Teleport to="body"><div v-if="selected" class="response-layer" @mousedown.self="close"><section><header><div><small>RESPONDER SOLICITUD</small><h3>{{responseType==='approve'?'Aprobar':'Rechazar'}} autorización</h3></div><button class="btn-close" :disabled="saving" @click="close"></button></header><form @submit.prevent="submit"><div class="modal-body"><div v-if="modalError" class="alert alert-danger">{{modalError}}</div><p>Paquete: <strong>{{selected.paquete?.nombre||'Paquete adicional'}}</strong></p><label class="form-label">Observaciones {{responseType==='reject'?'*':''}}</label><textarea v-model.trim="observations" class="form-control" rows="3" maxlength="500" :required="responseType==='reject'"></textarea><label class="form-label mt-3">Cargo</label><input v-model.trim="position" class="form-control"></div><footer><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="close">Cancelar</button><button class="btn" :class="responseType==='approve'?'btn-success':'btn-danger'" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Confirmar</button></footer></form></section></div></Teleport></main></template>
<script setup>import{onMounted,reactive,ref,watch}from'vue';import{obtenerMensajeError}from'@/services/api';import{aprobarAutorizacion,listarAutorizacionesPendientes,rechazarAutorizacion}from'@/services/referencias';const items=ref([]),loading=ref(false),error=ref(''),selected=ref(null),responseType=ref(''),observations=ref(''),position=ref(''),saving=ref(false),modalError=ref(''),filters=reactive({urgentes:false});const array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[];async function load(){loading.value=true;error.value='';try{items.value=array(await listarAutorizacionesPendientes({estado:'PENDIENTE',sin_responder:true,...(filters.urgentes?{urgentes:true}:{})}))}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}function respond(item,type){selected.value=item;responseType.value=type;observations.value='';position.value='';modalError.value=''}function close(){if(!saving.value)selected.value=null}async function submit(){saving.value=true;try{const referenceId=selected.value.referencia_id||selected.value.referencia?.id,payload={observaciones:observations.value,cargo:position.value};responseType.value==='approve'?await aprobarAutorizacion(referenceId,selected.value.id,payload):await rechazarAutorizacion(referenceId,selected.value.id,payload);selected.value=null;await load()}catch(e){modalError.value=obtenerMensajeError(e)}finally{saving.value=false}}watch(()=>filters.urgentes,load);onMounted(load)</script>
<style scoped>.auth-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#0b5688,#148fbd);color:#fff}.auth-hero span{font-size:.6rem;font-weight:800;letter-spacing:.08em}.auth-hero h1{margin:.2rem 0;font-size:1.5rem}.auth-hero p{margin:0;opacity:.82}.auth-hero>div:last-child{display:flex;align-items:center;gap:.8rem}.auth-hero label{display:flex;gap:.4rem;font-size:.7rem}.auth-list{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem}.auth-list>article{overflow:hidden;border:1px solid #dfe7ee;border-top:3px solid #4b9ac7;border-radius:.85rem;background:#fff;box-shadow:0 8px 24px rgba(24,64,96,.06)}.auth-list>article.urgent{border-top-color:#d65050}.auth-list article>header{display:flex;justify-content:space-between;padding:1rem;border-bottom:1px solid #e5ebf0}.auth-list header>div>span{display:block;color:#c43e48;font-size:.58rem;font-weight:800}.auth-list header small{color:#718096}.auth-list h3{margin:.2rem 0;font-size:.92rem}.status{height:max-content;padding:.3rem .55rem;border-radius:20px;background:#fff4df;color:#b6711c;font-size:.62rem}.auth-body{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem;padding:1rem}.auth-body small,.auth-body strong{display:block}.auth-body small{color:#8491a1;font-size:.58rem}.auth-body strong{font-size:.7rem}.reason{grid-column:1/-1;padding:.7rem;border-radius:.6rem;background:#f7f9fb}.reason p{margin:.2rem 0 .6rem;font-size:.68rem}.auth-list article>footer{display:flex;justify-content:flex-end;gap:.5rem;padding:.8rem 1rem;border-top:1px solid #e5ebf0}.empty{grid-column:1/-1;text-align:center;padding:5rem;color:#718096}.empty i{font-size:3rem;color:#adc3d2}.response-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:1rem;background:#071522b8;backdrop-filter:blur(5px)}.response-layer>section{width:min(500px,100%);border-radius:1rem;background:#fff}.response-layer section>header{display:flex;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e4eaf0}.response-layer header small{color:var(--bs-primary);font-size:.58rem;font-weight:800}.response-layer h3{margin:.1rem 0;font-size:1.05rem}.response-layer .modal-body{padding:1.2rem}.response-layer form>footer{display:flex;justify-content:flex-end;gap:.6rem;padding:1rem 1.2rem;border-top:1px solid #e4eaf0}@media(max-width:800px){.auth-list{grid-template-columns:1fr}.auth-hero{align-items:flex-start;flex-direction:column;gap:1rem}}</style>
